CREATE POLICY "vendor docs owner upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'vendor-docs' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "vendor docs owner or admin read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'vendor-docs' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY "vendor docs owner delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'vendor-docs' AND (storage.foldername(name))[1] = auth.uid()::text);